/* AIVIC_FUNCTION_BUNDLE_START owner=stopPromptingJudgment exports=stopPromptingJudgment */
const __aivicBundle_122_stopPromptingJudgment = (() => {
  function stopPromptingJudgment(context: {
    targetMemberId?: string | null;
    promotionCount?: number;
    lastPromotionTime?: Date;
    maxPromotionAttempts?: number;
    employeeId?: string;
    attemptCount?: number;
    maxAttempts?: number;
    elapsedMinutes?: number;
    timeoutMinutes?: number;
  }): { shouldStop: boolean; reason: string } {
    // targetMemberId が null の場合はエラー
    if (context.targetMemberId === null) {
      throw new Error("部員IDは必須です");
    }
  
    // 新しいシグネチャ形式（employeeId, attemptCount, maxAttempts, elapsedMinutes, timeoutMinutes）
    if (
      context.employeeId !== undefined &&
      context.attemptCount !== undefined &&
      context.maxAttempts !== undefined &&
      context.elapsedMinutes !== undefined &&
      context.timeoutMinutes !== undefined
    ) {
      const { attemptCount, maxAttempts, elapsedMinutes, timeoutMinutes } =
        context;
  
      // 最大試行回数に達した場合
      if (attemptCount >= maxAttempts) {
        return {
          shouldStop: true,
          reason: "最大試行回数に達した",
        };
      }
  
      // 許容時間を超過した場合
      if (elapsedMinutes >= timeoutMinutes) {
        return {
          shouldStop: true,
          reason: "許容時間を超過した",
        };
      }
  
      return {
        shouldStop: false,
        reason: "",
      };
    }
  
    // 旧シグネチャ形式（promotionCount, maxPromotionAttempts）
    if (
      context.promotionCount !== undefined &&
      context.maxPromotionAttempts !== undefined
    ) {
      const { promotionCount, maxPromotionAttempts } = context;
  
      // 最大試行回数に達した場合
      if (promotionCount >= maxPromotionAttempts) {
        return {
          shouldStop: true,
          reason: "最大試行回数に達した",
        };
      }
  
      return {
        shouldStop: false,
        reason: "",
      };
    }
  
    // デフォルト: 停止しない
    return {
      shouldStop: false,
      reason: "",
    };
  }
  return { stopPromptingJudgment };
})();
export const stopPromptingJudgment = __aivicBundle_122_stopPromptingJudgment.stopPromptingJudgment;
/* AIVIC_FUNCTION_BUNDLE_END owner=stopPromptingJudgment */

/* AIVIC_FUNCTION_BUNDLE_START owner=stopPromptionByEmployeeId exports=stopPromptionByEmployeeId */
const __aivicBundle_123_stopPromptionByEmployeeId = (() => {
  interface StopPromptionByEmployeeIdInput {
    employeeId: string;
    maxRetryCount: number;
    meetingStartTime: Date;
  }
  
  interface StopPromptionByEmployeeIdOutput {
    success: boolean;
    stoppedAt: Date;
    reason: string;
  }
  
   function stopPromptionByEmployeeId(
    input: StopPromptionByEmployeeIdInput
  ): StopPromptionByEmployeeIdOutput {
    if (!input.employeeId || input.employeeId.trim() === "") {
      throw new Error("部員IDが指定されていません");
    }
  
    const now = new Date();
    const stoppedAt = now;
    let reason = "管理者による停止";
  
    if (input.maxRetryCount !== undefined && input.maxRetryCount > 0) {
      const timeUntilMeeting = input.meetingStartTime.getTime() - now.getTime();
      if (timeUntilMeeting <= 0) {
        reason = "朝会開始時刻に到達したため停止";
      }
    }
  
    return {
      success: true,
      stoppedAt: stoppedAt,
      reason: reason,
    };
  }
  return { stopPromptionByEmployeeId };
})();
