/* AIVIC_FUNCTION_BUNDLE_START owner=sendUnreportedReminderEmails exports=sendUnreportedReminderEmails */
const __aivicBundle_163_sendUnreportedReminderEmails = (() => {
  function sendUnreportedReminderEmails(input: {
    meeting_start_time?: Date;
    current_time?: Date;
    unreported_user_ids?: string[];
    unreportedEmployees?: Array<{
      employeeId: string;
      employeeName: string;
      email: string;
      departmentId: string;
    }>;
    departmentHeadEmail?: string;
    reportDate?: string;
    deadlineTime?: Date;
  }): MailSendResult & { skipped?: boolean; skip_reason?: string } {
    const now = input.current_time || new Date();
    const meetingStartTime = input.meeting_start_time;
  
    if (meetingStartTime && now >= meetingStartTime) {
      return {
        success: false,
        emailsSent: 0,
        failedRecipients: [],
        messageIds: [],
        sentAt: now,
        skipped: true,
        skip_reason: "朝会開始時刻を過ぎているため、催促メール送信をスキップしました",
      };
    }
  
    const unreportedEmployees = input.unreportedEmployees || [];
    const failedRecipients: string[] = [];
    const messageIds: string[] = [];
    let emailsSent = 0;
  
    for (const employee of unreportedEmployees) {
      if (!isValidEmailFormat(employee.email)) {
        failedRecipients.push(employee.email);
        continue;
      }
  
      const messageId = `msg_${generateUniqueId()}`;
      messageIds.push(messageId);
      emailsSent++;
    }
  
    const success = failedRecipients.length === 0 && emailsSent > 0;
    const errorMessage =
      failedRecipients.length > 0
        ? "メールアドレス形式が不正です"
        : undefined;
  
    return {
      success,
      emailsSent,
      failedRecipients,
      messageIds,
      sentAt: now,
      errorMessage,
    };
  }
  
  function isValidEmailFormat(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }
  
  function generateUniqueId(): string {
    const { randomUUID } = require("crypto");
    return randomUUID().substring(0, 8);
  }
  return { sendUnreportedReminderEmails };
})();
export const sendUnreportedReminderEmails = __aivicBundle_163_sendUnreportedReminderEmails.sendUnreportedReminderEmails;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendUnreportedReminderEmails */

